#!/usr/bin/env node
// scripts/api-report.mjs — public API report (DESIGN.md §1.4 item 4, §1.3 extra rules; AL §10.4).
// Concatenates dist/api/index.d.ts and every declaration file it reaches through relative imports into
// etc/claude-code-driver.api.d.ts (sorted, with file banners), greps it for leaked L0/L1/L2-internal type names, and fails when
// the result differs from the committed report. Run after `pnpm build`.
//   node scripts/api-report.mjs            check (exit 1 on leak or diff, 2 when dist/ is missing)
//   node scripts/api-report.mjs --update   rewrite etc/claude-code-driver.api.d.ts (still fails on a leak)
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const ENTRY = join(root, 'dist', 'api', 'index.d.ts');
const REPORT = join(root, 'etc', 'claude-code-driver.api.d.ts');

/** §1.3: no L0/L1/L2-internal type may appear in the public declarations. */
export const LEAK_RE =
  /\b(?:Tmux\w*|TailLine|TailEvent|RawHookEvent|ScreenSnapshot|TunnelRecord|Capture\b|Fact<|SessionState|SessionSpec|ResolvedConfig|CoreConfig|Observation\w*|DomainEvent|Intent\b|ReconState)/g;

/** Removes comments so documentation prose cannot trigger the leak grep. String literals are kept intact. */
export function stripComments(src) {
  let out = '';
  let i = 0;
  while (i < src.length) {
    const c = src[i];
    const n = src[i + 1];
    if (c === '"' || c === "'" || c === '`') {
      const q = c;
      let j = i + 1;
      while (j < src.length && src[j] !== q) j += src[j] === '\\' ? 2 : 1;
      out += src.slice(i, j + 1);
      i = j + 1;
    } else if (c === '/' && n === '/') {
      while (i < src.length && src[i] !== '\n') i++;
    } else if (c === '/' && n === '*') {
      const end = src.indexOf('*/', i + 2);
      i = end < 0 ? src.length : end + 2;
    } else {
      out += c;
      i++;
    }
  }
  return out;
}

/** Replaces the contents of string literals with spaces (string literal types such as `'Intent'` are not type references). */
export function blankStrings(src) {
  return src.replace(/(['"`])((?:\\.|(?!\1)[^\\\n])*)\1/g, (_m, q, body) => `${q}${' '.repeat(body.length)}${q}`);
}

/**
 * @param {string} text declaration text
 * @returns {Array<{ line: number; name: string; text: string }>}
 */
export function findLeaks(text) {
  const leaks = [];
  const lines = blankStrings(stripComments(text)).split('\n');
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i] ?? '';
    for (const m of l.matchAll(LEAK_RE)) leaks.push({ line: i + 1, name: m[0], text: l.trim() });
  }
  return leaks;
}

const IMPORT_RE = /(?:\bfrom\s*|\bimport\s*\(\s*|\bimport\s+)(['"])(\.{1,2}\/[^'"]+)\1/g;

/** @param {string} file absolute .d.ts path @returns {string[]} absolute .d.ts paths it references */
function references(file) {
  const out = [];
  const src = readFileSync(file, 'utf8');
  for (const m of src.matchAll(IMPORT_RE)) {
    const spec = m[2] ?? '';
    const base = resolve(dirname(file), spec);
    const candidates = [base.replace(/\.js$/, '.d.ts'), `${base}.d.ts`, join(base, 'index.d.ts')];
    const hit = candidates.find((p) => existsSync(p));
    if (hit !== undefined) out.push(hit);
  }
  return out;
}

/** @param {string} entry @returns {string} the concatenated report text */
export function buildReport(entry) {
  const seen = new Set();
  const queue = [entry];
  while (queue.length > 0) {
    const f = queue.shift();
    if (f === undefined || seen.has(f)) continue;
    seen.add(f);
    queue.push(...references(f));
  }
  const distRoot = join(root, 'dist');
  const files = [...seen].sort((a, b) => (a === entry ? -1 : b === entry ? 1 : a < b ? -1 : a > b ? 1 : 0));
  const parts = ['// GENERATED by scripts/api-report.mjs — the public declaration surface of `claude-code-driver`. Review every diff.', ''];
  for (const f of files) {
    const body = readFileSync(f, 'utf8')
      .replace(/^\/\/# sourceMappingURL=.*$/gm, '')
      .trimEnd();
    parts.push(`// ===== ${relative(distRoot, f)} =====`, body, '');
  }
  return parts.join('\n');
}

function main() {
  if (!existsSync(ENTRY)) {
    process.stderr.write('api-report: dist/api/index.d.ts not found; run `pnpm build` first\n');
    process.exit(2);
  }
  const report = buildReport(ENTRY);
  const leaks = findLeaks(report);
  if (leaks.length > 0) {
    for (const l of leaks) process.stderr.write(`api-report: internal type "${l.name}" leaks into the public API: ${l.text}\n`);
    process.exit(1);
  }
  if (process.argv.includes('--update')) {
    mkdirSync(dirname(REPORT), { recursive: true });
    writeFileSync(REPORT, report);
    process.stdout.write(`api-report: wrote ${relative(root, REPORT)}\n`);
    return;
  }
  const committed = existsSync(REPORT) ? readFileSync(REPORT, 'utf8') : undefined;
  if (committed !== report) {
    process.stderr.write(
      `api-report: public API differs from ${relative(root, REPORT)}; review and run \`node scripts/api-report.mjs --update\`\n`,
    );
    process.exit(1);
  }
  process.stdout.write('api-report: ok\n');
}

if (process.argv[1] !== undefined && fileURLToPath(import.meta.url) === process.argv[1]) main();
